```json
{
  "root_causes": [
    {
      "service": "geo",
      "fault_kind": "network_delay",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT c.service_name AS caller, s.service_name AS callee, count(*) AS n, round(quantile_cont(c.duration/1e6,0.5),1) AS client_p50_ms, round(quantile_cont(s.duration/1e6,0.5),3) AS server_p50_ms, round(quantile_cont((c.duration-s.duration)/1e6,0.5),1) AS gap_p50_ms FROM abnormal_traces c JOIN abnormal_traces s ON s.parent_span_id=c.span_id AND s.trace_id=c.trace_id WHERE c.service_name='search' AND c.span_name='geo.Geo/Nearby' AND s.service_name='geo' GROUP BY 1,2",
          "claim": "search to geo Nearby calls take about 1.4 s client-side, while geo's server span is about 0.14 ms."
        },
        {
          "kind": "trace",
          "sql": "SELECT c.service_name AS caller, c.span_name, round(quantile_cont(c.duration/1e6,0.5),2) AS abn_client_p50_ms FROM abnormal_traces c WHERE c.service_name='search' AND c.span_name='rate.Rate/GetRates' AND c.attr_span_kind='Client' UNION ALL SELECT c.service_name, c.span_name, round(quantile_cont(c.duration/1e6,0.5),2) FROM normal_traces c WHERE c.service_name='search' AND c.span_name='geo.Geo/Nearby' AND c.attr_span_kind='Client'",
          "claim": "Search's other outgoing call to rate stays fast, so the delay is specific to the search-to-geo connection."
        },
        {
          "kind": "metric",
          "sql": "SELECT metric, service_name, round(avg(CASE WHEN src='n' THEN value END),1) normal_avg, round(avg(CASE WHEN src='a' THEN value END),1) abn_avg FROM (SELECT 'n' src, * FROM normal_metrics_sum UNION ALL SELECT 'a', * FROM abnormal_metrics_sum) WHERE metric IN ('k8s.pod.network.errors','k8s.pod.network.io') AND service_name IN ('search','geo') GROUP BY 1,2",
          "claim": "Network errors stay at zero and network I/O barely changes on search and geo pods; no packet loss or restarts."
        }
      ]
    }
  ],
  "propagation": [
    {
      "from": "geo",
      "to": "search",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT s.service_name, s.span_name, round(quantile_cont(s.duration/1e6,0.95),1) AS server_p95_ms, round(quantile_cont(s.duration/1e6,0.5),1) AS p50_ms FROM abnormal_traces s WHERE s.service_name='search' AND s.attr_span_kind='Server' GROUP BY 1,2",
          "claim": "search Nearby server spans rise to about 2.6 s p95 (from about 8.5 ms in normal), driven by the geo call wait."
        }
      ]
    },
    {
      "from": "search",
      "to": "frontend",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT c.service_name AS caller, s.service_name AS callee, round(quantile_cont(c.duration/1e6,0.95),1) AS client_p95_ms, round(quantile_cont(s.duration/1e6,0.95),1) AS server_p95_ms FROM abnormal_traces c JOIN abnormal_traces s ON s.parent_span_id=c.span_id AND s.trace_id=c.trace_id WHERE c.service_name='frontend' AND s.service_name='search' GROUP BY 1,2",
          "claim": "frontend's search.Search/Nearby client span matches search's server span at about 2.6 s p95; the HTTP /hotels path inherits this delay."
        }
      ]
    }
  ]
}
